// Generated by tools/sim/replay.py from a stage 6 solution.
// One rising edge per cycle; inputs applied while the clock is low
// and outputs sampled before the edge, which is the cycle model
// tools/stage6_invert.py unrolls.

`timescale 1ns / 1ps

module tb_solution;
  reg clk = 1'b0;
  reg [0:0] A;
  reg [0:0] B;
  reg [0:0] en;
  reg [0:0] rst_n;
  wire S;
  integer mismatches = 0;
  integer unknown = 0;

  adder_demo dut (.A(A), .B(B), .S(S), .clk(clk), .en(en), .rst_n(rst_n));

  initial begin
    // cycle 0
    A = 1'd1;
    B = 1'd1;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("cycle %0d   S=%b   model says S=0", 0, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;

    // cycle 1
    A = 1'd1;
    B = 1'd1;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("cycle %0d   S=%b   model says S=0", 1, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;

    // cycle 2
    A = 1'd1;
    B = 1'd1;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("cycle %0d   S=%b   model says S=0", 2, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;

    // cycle 3
    A = 1'd1;
    B = 1'd1;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("cycle %0d   S=%b   model says S=0", 3, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;

    // cycle 4
    A = 1'd1;
    B = 1'd0;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("cycle %0d   S=%b   model says S=0", 4, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;

    // cycle 5
    A = 1'd1;
    B = 1'd1;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("cycle %0d   S=%b   model says S=0", 5, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;

    // cycle 6
    A = 1'd0;
    B = 1'd0;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("cycle %0d   S=%b   model says S=0", 6, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;

    // cycle 7
    A = 1'd0;
    B = 1'd0;
    en = 1'd1;
    rst_n = 1'd1;
    #4;
    $display("cycle %0d   S=%b   model says S=0", 7, S);
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;

    // cycle 8
    A = 1'd0;
    B = 1'd0;
    en = 1'd0;
    rst_n = 1'd1;
    #4;
    $display("cycle %0d   S=%b   model says S=1", 8, S);
    if (S === 1'b1)
      $display("  the property holds: S is 1 at cycle %0d", 8);
    else if (S === 1'bx)
      begin unknown = unknown + 1;
        $display("  S is x at cycle %0d: the trace does not flush this design's state", 8); end
    else
      begin mismatches = mismatches + 1;
        $display("  S is %b at cycle %0d and the model said 1", S, 8); end
    #1 clk = 1'b1;
    #4;
    #1 clk = 1'b0;

    $display("");
    $display("cycles replayed  9");
    $display("property        S high at cycle 8");
    $display("mismatches      %0d", mismatches);
    $display("unknown         %0d", unknown);
    if (mismatches == 0 && unknown == 0)
      $display("RESULT: pass");
    else
      $display("RESULT: FAIL");
    $finish;
  end

endmodule
